compile_rc=$?
print -r -- "compile_exit_code=$compile_rc" > dev_status.log
if [ "$compile_rc" -eq 0 ]; then
    timeout 30s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > dev_simulation.log 2>&1
    simulation_rc=$?
    print -r -- "simulation_exit_code=$simulation_rc" >> dev_status.log
fi'

